using GraphApi.Models.ENC.Encuestas;namespace GraphApi.Services.ENC.Encuestas{    /// <summary>    /// Define las operaciones de negocio y persistencia para Encuestas.    /// </summary>    public interface IEncuestasService    {        /// <summary>        /// Obtiene la lista de Encuestas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadEncuestas>> GetEncuestas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Encuestas con filtros opcionales.        /// </summary>        /// <param name="encuestaID">Filtro opcional para EncuestaID.</param>        /// <param name="titulo">Filtro opcional para Titulo.</param>        /// <param name="descripcion">Filtro opcional para Descripcion.</param>        /// <param name="fechaInicio">Filtro opcional para FechaInicio.</param>        /// <param name="fechaFin">Filtro opcional para FechaFin.</param>        /// <param name="bActivo">Filtro opcional para bActivo.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetEncuestasDynamic(            int? encuestaID,            string? titulo,            string? descripcion,            DateTime? fechaInicio,            DateTime? fechaFin,            bool? bActivo,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Encuesta.        /// </summary>        /// <param name="objInput">Datos para crear el Encuesta.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadEncuestas> CreateEncuestas(            clCreateEncuestas objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Encuesta.        /// </summary>        /// <param name="objInput">Datos para actualizar el Encuesta, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadEncuestas?> UpdateEncuestas(            clUpdateEncuestas objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Encuesta por su ID.        /// </summary>        /// <param name="nEncuestasID">ID del Encuesta a eliminar.</param>        Task<bool> DeleteEncuestas(int nEncuestasID);    }}